#!/usr/bin/env python3
"""Write js/blitzimg.js: BLITZ!.128 (V860929) as base64, so the port needs no extra input file."""
import base64, os, hashlib
H = os.path.dirname(os.path.abspath(__file__))
b = open(os.path.join(H, '..', '..', 'blitz!.128.prg'), 'rb').read()
s = base64.b64encode(b).decode()
lines = '\n'.join(repr(s[i:i + 100]) + ' +' for i in range(0, len(s), 100))[:-2]
open(os.path.join(H, '..', 'js', 'blitzimg.js'), 'w').write(
    '// GENERATED by tools/embed.py: BLITZ!.128 (Skyles, V860929), %d bytes, sha1 %s\n'
    '// Source of the runtime images copied into every C/ file.\n'
    'export const BLITZ_B64 =\n%s;\n' % (len(b), hashlib.sha1(b).hexdigest(), lines.replace("'", '"')))
print('js/blitzimg.js', len(b), 'bytes')
